I add a plugin to resolve it 
add 
~/.config/opencode/plugin/myArgPatch.ts

```ts
import { Plugin } from "@opencode-ai/plugin"

export const myArgPatch: Plugin = async (ctx) => {
  return {
    auth: {
      provider: "YUOR_PROVDER_NAME",
      loader: async (getAuth, provider) => {
        return {
          async fetch(input, init) {
            const opts = init ?? {}
            if (opts.body && typeof opts.body === "string") {
              try {
                const body = JSON.parse(opts.body)

                //  delete this arg 
                delete body.reasoningSummary
                opts.body = JSON.stringify(body)
              } catch (e) {}
            }
            return fetch(input, {
              ...opts,
              timeout: false,
            })
          },
        }
      },
    },
  }
}

```


in  ~/config/opencode/opencode.jsonc

```json
{
...
  "plugin": ["myArgPatch"],
}
```
